import { clsx, type ClassValue } from "clsx"
import { twMerge } from "tailwind-merge"

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

"use client";

import React, { useEffect, useRef, useState } from "react";
import { Moon, Sun, Menu, X } from "lucide-react";
import { motion, useReducedMotion } from "framer-motion";
import Link from "next/link";
import { useTheme } from "next-themes";
import { cn } from "@/lib/utils";




/* -------------------------------------------------------------------------- */
/*                                   TYPES                                    */
/* -------------------------------------------------------------------------- */


export type NavbarItem = {
  label: string;
  href: string;
};

type NavbarProps = {
  position?: "fixed" | "relative";
  items?: NavbarItem[];
  className?: string;
  logo?: React.ReactNode;
  brandText?: React.ReactNode;
  brandClassName?: string;
};

const DEFAULT_NAV_ITEMS: NavbarItem[] = [
  { label: "Docs", href: "/docs" },
  { label: "Components", href: "/docs/components" },
  { label: "Templates", href: "/templates" },
  { label: "Pricing", href: "/pricing" },
];

/* -------------------------------------------------------------------------- */
/*                                   NAVBAR                                   */
/* -------------------------------------------------------------------------- */

export default function Navbar({
  position = "fixed",
  items = DEFAULT_NAV_ITEMS,
  className,
  logo,
  brandText = "ZENBLOCKS",
  brandClassName
}: NavbarProps) {
  const [scrolled, setScrolled] = useState(false);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const prefersReduced = useReducedMotion();

  useEffect(() => {
    if (position === "relative") return;

    const onScroll = () => setScrolled(window.scrollY > 50);
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => window.removeEventListener("scroll", onScroll);
  }, [position]);

  const navLinks = items;

  return (
    <div
      className={cn(
        "z-50 px-3 mt-3 pointer-events-none",
        position === "fixed"
          ? "fixed top-0 left-0 right-0 flex justify-center"
          : "relative w-full"
      )}
    >
      <nav
        aria-label="Main Navigation"
        className={cn(
          "pointer-events-auto w-full rounded-2xl px-4 py-2 border transition-all duration-300",
          position === "fixed" ? "max-w-3xl mx-auto" : "max-w-full",
          scrolled && position === "fixed"
            ? "bg-white/50 dark:bg-zinc-900/50 backdrop-blur-xl shadow-md border-zinc-200/50 dark:border-white/10"
            : "bg-white/10 dark:bg-zinc-900/10 backdrop-blur-lg border-zinc-900/5 dark:border-white/5",
          "text-zinc-900 dark:text-white", // Default text color
          className
        )}
      >
        <div className="relative flex items-center h-10">
          {/* LOGO */}
          <div className="absolute left-0 flex items-center gap-2">
            <Link href="/" className="flex items-center gap-2">
              {logo ?? <CompactLogo prefersReduced={!!prefersReduced} />}
              <span className={cn("text-sm font-semibold tracking-tight text-current", brandClassName)}>
                {brandText}
              </span>
            </Link>
          </div>

          {/* CENTER NAV */}
          <div className="flex-1 flex justify-center">
            <div className="hidden sm:block">
              <SlideTabs
                navLinks={navLinks}
                prefersReduced={!!prefersReduced}
              />
            </div>
          </div>

          {/* RIGHT CONTROLS */}
          <div className="absolute right-0 flex items-center gap-2">
            <ThemeButton />

            <button
              onClick={() => setMobileMenuOpen((s) => !s)}
              className="sm:hidden p-1.5 rounded-md hover:bg-black/5 dark:hover:bg-white/5 transition"
              aria-label="Toggle menu"
            >
              {mobileMenuOpen ? (
                <X className="w-5 h-5 text-current" />
              ) : (
                <Menu className="w-5 h-5 text-current" />
              )}
            </button>
          </div>
        </div>

        {/* MOBILE MENU */}
        {mobileMenuOpen && (
          <div className="sm:hidden mt-3 pt-3 border-t border-black/10 dark:border-white/10 flex flex-col gap-2 bg-transparent">
            {navLinks.map((link) => (
              <Link
                key={link.href}
                href={link.href}
                onClick={() => setMobileMenuOpen(false)}
                className="px-3 py-2 rounded-md text-sm font-medium text-current hover:bg-black/5 dark:hover:bg-white/5"
              >
                {link.label}
              </Link>
            ))}
          </div>
        )}
      </nav>
    </div>
  );
}

/* -------------------------------------------------------------------------- */
/*                                   LOGO                                     */
/* -------------------------------------------------------------------------- */

function CompactLogo({ prefersReduced }: { prefersReduced: boolean }) {
  const blocks = [
    "bg-neutral-900 dark:bg-neutral-300",
    "bg-neutral-600 dark:bg-neutral-500",
    "bg-neutral-400 dark:bg-neutral-700",
  ];

  return (
    <div className="flex gap-0.5 w-5 h-5 items-center">
      {blocks.map((cls, i) => (
        <motion.div
          key={i}
          className={`w-2 h-2 rounded-sm ${cls}`}
          animate={prefersReduced ? undefined : { y: [0, -3, 0] }}
          transition={{
            duration: 1.1,
            repeat: Infinity,
            ease: "easeInOut",
            delay: i * 0.12,
          }}
        />
      ))}
    </div>
  );
}

/* -------------------------------------------------------------------------- */
/*                               THEME BUTTON                                 */
/* -------------------------------------------------------------------------- */

function ThemeButton() {
  const { setTheme, resolvedTheme } = useTheme();
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    setMounted(true);
  }, []);

  if (!mounted) {
    return (
      <div className="w-8 h-8 rounded-md border border-zinc-200 dark:border-zinc-800" />
    );
  }

  const isDark = resolvedTheme === "dark";

  return (
    <button
      onClick={() => setTheme(isDark ? "light" : "dark")}
      className="relative w-9 h-9 flex items-center justify-center rounded-xl transition-all duration-300
        bg-zinc-100 dark:bg-zinc-800/50 hover:bg-zinc-200 dark:hover:bg-zinc-800 
        border border-zinc-200 dark:border-zinc-700/50"
      aria-label="Toggle theme"
    >
      <div className="relative w-5 h-5 overflow-hidden">
        <motion.div
          animate={{
            y: isDark ? 0 : 25,
            opacity: isDark ? 1 : 0,
            rotate: isDark ? 0 : -45,
          }}
          transition={{ type: "spring", stiffness: 300, damping: 20 }}
          className="absolute inset-0 flex items-center justify-center"
        >
          <Sun className="w-5 h-5 text-amber-400 fill-amber-400/20" />
        </motion.div>

        <motion.div
          animate={{
            y: isDark ? -25 : 0,
            opacity: isDark ? 0 : 1,
            rotate: isDark ? 45 : 0,
          }}
          transition={{ type: "spring", stiffness: 300, damping: 20 }}
          className="absolute inset-0 flex items-center justify-center"
        >
          <Moon className="w-5 h-5 text-zinc-900 fill-zinc-900/10" />
        </motion.div>
      </div>

      {/* Subtle Glow */}
      <motion.div
        animate={{
          opacity: isDark ? 0.5 : 0,
        }}
        className="absolute inset-0 rounded-xl bg-amber-400/20 blur-md pointer-events-none"
      />
    </button>
  );
}






/* -------------------------------------------------------------------------- */
/*                                SLIDE TABS                                  */
/* -------------------------------------------------------------------------- */

function SlideTabs({
  navLinks,
  prefersReduced,
}: {
  navLinks: { label: string; href: string }[];
  prefersReduced: boolean;
}) {
  const containerRef = useRef<HTMLUListElement | null>(null);
  const [position, setPosition] = useState({
    left: 0,
    width: 0,
    opacity: 0,
  });

  return (
    <ul
      ref={containerRef}
      onMouseLeave={() => setPosition((p) => ({ ...p, opacity: 0 }))}
      className="relative flex items-center h-9 px-1 rounded-full"
      role="menubar"
    >
      {navLinks.map((link) => (
        <CompactTab
          key={link.href}
          href={link.href}
          containerRef={containerRef}
          setPosition={setPosition}
        >
          {link.label}
        </CompactTab>
      ))}

      <motion.li
        aria-hidden
        animate={position}
        transition={
          prefersReduced
            ? { duration: 0 }
            : { type: "spring", stiffness: 380, damping: 32 }
        }
        className="absolute top-0 h-9 rounded-full bg-zinc-900 dark:bg-zinc-100/10"
      />
    </ul>
  );
}

/* -------------------------------------------------------------------------- */
/*                                  TAB ITEM                                  */
/* -------------------------------------------------------------------------- */

interface CompactTabProps {
  children: React.ReactNode;
  href: string;
  containerRef: React.RefObject<HTMLUListElement | null>;
  setPosition: React.Dispatch<
    React.SetStateAction<{ left: number; width: number; opacity: number }>
  >;
}

const CompactTab: React.FC<CompactTabProps> = ({
  children,
  href,
  containerRef,
  setPosition,
}) => {
  const ref = useRef<HTMLAnchorElement | null>(null);

  const update = () => {
    if (!ref.current || !containerRef.current) return;

    const rect = ref.current.getBoundingClientRect();
    const parent = containerRef.current.getBoundingClientRect();

    setPosition({
      left: rect.left - parent.left,
      width: rect.width,
      opacity: 1,
    });
  };

  return (
    <li className="relative z-10 h-9 flex items-center" role="none">
      <Link
        ref={ref}
        href={href}
        onMouseEnter={update}
        onFocus={update}
        onBlur={() => setPosition((p) => ({ ...p, opacity: 0 }))}
        className="group flex items-center h-9 px-4 rounded-full text-sm font-medium text-current focus:outline-none"
        role="menuitem"
      >
        <span className="relative z-10 transition-colors group-hover:text-white group-focus:text-white opacity-80 group-hover:opacity-100">
          {children}
        </span>
      </Link>
    </li>
  );
};

"use client";

import React, { useRef } from "react";
import { useGSAP } from "@gsap/react";
import gsap from "gsap";
import { cn } from "@/lib/utils";

/* -------------------------------------------------------------------------- */
/*                                   TYPES                                    */
/* -------------------------------------------------------------------------- */


export type PreLoaderProps = {
  onComplete?: () => void;
  /**
   * The text to display during the loading animation.
   * @default "S"
   */
  text?: string;
  /**
   * When true, renders inside a container instead of fullscreen.
   * Used for docs / previews.
   */
  embedded?: boolean;
  className?: string;
};

/* -------------------------------------------------------------------------- */
/*                                PRELOADER                                   */
/* -------------------------------------------------------------------------- */

const PreLoader: React.FC<PreLoaderProps> = ({
  onComplete,
  text = "Z",
  embedded = false,
  className,
}) => {
  const screenRef = useRef<HTMLDivElement | null>(null);
  const textRef = useRef<HTMLDivElement | null>(null);
  const percentRef = useRef<HTMLDivElement | null>(null);

  useGSAP(
    () => {
      if (!screenRef.current || !textRef.current || !percentRef.current) return;

      /* ---------------------------- Initial State ---------------------------- */

      gsap.set(textRef.current, {
        scale: 0,
        rotation: 180,
      });

      gsap.set(percentRef.current, {
        opacity: 0,
        y: 20,
      });

      /* ------------------------------ Animate In ----------------------------- */

      gsap.to(textRef.current, {
        scale: 1,
        rotation: 0,
        duration: 1,
        ease: "back.out(1.7)",
      });

      gsap.to(percentRef.current, {
        opacity: 1,
        y: 0,
        duration: 0.5,
        delay: 0.5,
        ease: "power2.out",
      });

      /* ------------------------- Percentage Counter -------------------------- */

      gsap.to(percentRef.current, {
        innerHTML: 100,
        duration: 2.5,
        delay: 1,
        ease: "power2.inOut",
        snap: { innerHTML: 1 },
        onUpdate() {
          const el = this.targets()[0] as HTMLElement;
          const value = Math.round(Number(el.innerHTML));
          el.innerHTML = `${value}%`;
        },
      });

      /* ------------------------------ Pulse Hold ----------------------------- */

      gsap.to(textRef.current, {
        scale: 1.1,
        duration: 0.5,
        delay: 1,
        yoyo: true,
        repeat: 1,
        ease: "power2.inOut",
      });

      /* ------------------------------ Animate Out ----------------------------- */

      gsap.to(textRef.current, {
        scale: 0,
        rotation: -180,
        duration: 0.8,
        delay: 2.5,
        ease: "back.in(1.7)",
      });

      /* ---------------------------- Screen Fade ------------------------------ */

      gsap.to(screenRef.current, {
        opacity: 0,
        duration: 0.5,
        delay: 3.3,
        ease: "power1.inOut",
        onComplete: () => {
          onComplete?.();
        },
      });
    },
    { dependencies: [onComplete] }
  );

  return (
    <div
      ref={screenRef}
      className={cn(
        "z-50 pointer-events-none flex items-center justify-center",
        embedded ? "absolute inset-0" : "fixed inset-0",

        /* Surface */
        "bg-white text-zinc-900",
        "dark:bg-black dark:text-white",
        className
      )}
    >
      {/* Main Letter */}
      <div
        ref={textRef}
        className={cn(
          "text-[100px] sm:text-[150px] md:text-[200px]",
          "font-black tracking-tight",
          "text-current" // Force inheritance
        )}
      >
        {text}
      </div>

      {/* Percentage counter */}
      <div
        ref={percentRef}
        className={cn(
          "absolute bottom-6 right-6",
          "text-4xl sm:text-5xl md:text-6xl",
          "font-light italic",
          "opacity-60" // Use opacity instead of explicit color
        )}
      >
        0%
      </div>
    </div>
  );
};

export default PreLoader;

"use client";

import React, { useEffect, useState, useRef } from "react";
import { motion, AnimatePresence, useMotionValue, useSpring, useTransform } from "framer-motion";
import { cn } from "@/lib/utils";

interface DigitProps {
    value: string | number;
    className?: string;
}

const Digit = ({ value, className }: DigitProps) => {
    return (
        <div className={cn("relative h-[1.2em] w-[0.6em] overflow-hidden flex items-center justify-center font-mono text-4xl md:text-6xl font-black tracking-tighter", className)}>
            <AnimatePresence mode="popLayout">
                <motion.span
                    key={value}
                    initial={{ y: "100%", opacity: 0, filter: "blur(10px)", scale: 0.8 }}
                    animate={{ y: "0%", opacity: 1, filter: "blur(0px)", scale: 1 }}
                    exit={{ y: "-100%", opacity: 0, filter: "blur(10px)", scale: 0.8 }}
                    transition={{
                        type: "spring",
                        stiffness: 400,
                        damping: 30,
                        mass: 0.5,
                    }}
                    className="absolute inset-0 flex items-center justify-center"
                >
                    {value}
                </motion.span>
            </AnimatePresence>
        </div>
    );
};

const Separator = ({ className }: { className?: string }) => (
    <motion.div
        animate={{ opacity: [0.3, 1, 0.3] }}
        transition={{ duration: 1, repeat: Infinity, ease: "easeInOut" }}
        className={cn("text-4xl md:text-6xl font-bold px-1", className)}
    >
        :
    </motion.div>
);


export interface AnimatedClockProps {
    className?: string;
    /**
     * If true, displays time in 24-hour format (HH:MM:SS).
     * If false, displays in 12-hour format.
     * @default true
     */
    use24HourFormat?: boolean;
}

export const AnimatedClock = ({ className, use24HourFormat = true }: AnimatedClockProps) => {
    const [time, setTime] = useState(new Date());
    const [mounted, setMounted] = useState(false);
    const containerRef = useRef<HTMLDivElement>(null);

    // 3D Motion Values
    const x = useMotionValue(0);
    const y = useMotionValue(0);

    // Smooth springs for tilt
    const rotateX = useSpring(useTransform(y, [-0.5, 0.5], [15, -15]), { stiffness: 100, damping: 20 });
    const rotateY = useSpring(useTransform(x, [-0.5, 0.5], [-15, 15]), { stiffness: 100, damping: 20 });

    useEffect(() => {
        setMounted(true);
        const timer = setInterval(() => {
            setTime(new Date());
        }, 1000);
        return () => clearInterval(timer);
    }, []);

    const handleMouseMove = (event: React.MouseEvent<HTMLDivElement>) => {
        if (!containerRef.current) return;
        const rect = containerRef.current.getBoundingClientRect();

        // Normalize mouse position for 3D tilt (-0.5 to 0.5)
        const relativeX = (event.clientX - rect.left) / rect.width;
        const relativeY = (event.clientY - rect.top) / rect.height;
        x.set(relativeX - 0.5);
        y.set(relativeY - 0.5);
    };

    const handleMouseLeave = () => {
        x.set(0);
        y.set(0);
    };

    if (!mounted) {
        return (
            <div className={cn(
                "group relative flex items-center justify-center gap-1 p-12 rounded-[3.5rem] bg-white/40 dark:bg-zinc-950/20 backdrop-blur-2xl border border-white/50 dark:border-white/5 shadow-2xl transition-all duration-500 w-[350px] h-[150px]",
                className
            )} />
        );
    }

    let hours = time.getHours();
    if (!use24HourFormat) {
        hours = hours % 12 || 12; // Convert to 12h format
    }

    const hoursStr = hours.toString().padStart(2, "0");
    const minutesStr = time.getMinutes().toString().padStart(2, "0");
    const secondsStr = time.getSeconds().toString().padStart(2, "0");

    return (
        <motion.div
            ref={containerRef}
            onMouseMove={handleMouseMove}
            onMouseLeave={handleMouseLeave}
            style={{
                rotateX,
                rotateY,
                transformStyle: "preserve-3d",
            }}
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            className={cn(
                "group relative flex items-center justify-center gap-1 p-12 rounded-[3.5rem] bg-white/40 dark:bg-zinc-950/20 backdrop-blur-2xl border border-white/50 dark:border-white/5 shadow-2xl transition-all duration-500 w-fit cursor-default",
                className
            )}
        >
            <div className="flex items-center" style={{ transform: "translateZ(50px)" }}>
                <Digit value={hoursStr[0]} className="text-zinc-950 dark:text-white" />
                <Digit value={hoursStr[1]} className="text-zinc-950 dark:text-white" />
            </div>

            <Separator className="text-zinc-400 dark:text-zinc-600" />

            <div className="flex items-center" style={{ transform: "translateZ(50px)" }}>
                <Digit value={minutesStr[0]} className="text-zinc-950 dark:text-white" />
                <Digit value={minutesStr[1]} className="text-zinc-950 dark:text-white" />
            </div>

            <Separator className="text-zinc-400 dark:text-zinc-600" />

            <div className="flex items-center" style={{ transform: "translateZ(50px)" }}>
                <Digit value={secondsStr[0]} className="text-zinc-500 opacity-50" />
                <Digit value={secondsStr[1]} className="text-zinc-500 opacity-50" />
            </div>
        </motion.div>
    );
};

"use client";

import React from "react";
import { motion, useMotionValue, useSpring, useTransform } from "framer-motion";
import {
    ArrowRight,
    Box
} from "lucide-react";
import { cn } from "@/lib/utils";

const MotionDiv = motion.div as any;

/* -------------------------------------------------------------------------- */
/*                                 BENTOCARD                                  */
/* -------------------------------------------------------------------------- */

export interface BentoCardProps {
    children?: React.ReactNode;
    className?: string;
    /** Standard Props for Simple Mode */
    title?: string;
    description?: React.ReactNode;
    icon?: React.ReactNode;
    visual?: React.ReactNode;
    /** Animation Delay */
    delay?: number;
    /** Href for making the card a link */
    href?: string;
}

/**
 * BentoCard: A versatile card with magnetic spotlight and spring/hover effects.
 * 
 * Usage Modes:
 * 1. Simple: Pass `title`, `description`, `icon`, `visual`.
 * 2. Custom: Pass `children` to render arbitrary content inside the spotlight shell.
 */
export const BentoCard = ({
    children,
    className = "",
    title,
    description,
    icon,
    visual,
    delay = 0,
    href
}: BentoCardProps) => {
    const mouseX = useMotionValue(0);
    const mouseY = useMotionValue(0);

    const handleMouseMove = ({ currentTarget, clientX, clientY }: React.MouseEvent) => {
        const { left, top } = currentTarget.getBoundingClientRect();
        mouseX.set(clientX - left);
        mouseY.set(clientY - top);
    };

    const smoothX = useSpring(mouseX, { damping: 35, stiffness: 350 });
    const smoothY = useSpring(mouseY, { damping: 35, stiffness: 350 });

    const Container = href ? (motion.a as any) : MotionDiv;

    return (
        <Container
            href={href}
            initial={{ opacity: 0, y: 30 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true, margin: "-50px" }}
            whileHover={{ y: -8 }}
            transition={{
                y: { type: "spring", stiffness: 200, damping: 20 },
                opacity: { duration: 0.8, delay, ease: [0.16, 1, 0.3, 1] }
            }}
            onMouseMove={handleMouseMove}
            className={cn(
                "group relative flex flex-col overflow-visible rounded-[2rem] transition-all duration-500 text-left h-full",
                href && "cursor-pointer",
                className
            )}
        >
            {/* Dynamic Background Spotlight (Shared Logic) */}
            <div className={cn(
                "relative z-10 flex flex-col flex-1 overflow-hidden rounded-[2rem] bg-white/80 dark:bg-zinc-950/80 backdrop-blur-2xl border border-zinc-200 dark:border-zinc-800 transition-all duration-700 h-full",
                "group-hover:border-zinc-400 dark:group-hover:border-zinc-100/30",
                "group-hover:shadow-[0_48px_96px_-24px_rgba(0,0,0,0.15)] dark:group-hover:shadow-[0_48px_96px_-24px_rgba(255,255,255,0.03)]"
            )}>

                {/* Spotlights */}
                <MotionDiv
                    className="pointer-events-none absolute -inset-px z-10 opacity-0 transition-opacity duration-1000 group-hover:opacity-100"
                    style={{
                        background: useTransform(
                            [smoothX, smoothY],
                            ([x, y]: any[]) => `radial-gradient(400px circle at ${x}px ${y}px, rgba(0,0,0,0.03), transparent 70%)`
                        ),
                    }}
                />
                <MotionDiv
                    className="pointer-events-none absolute -inset-px z-10 opacity-0 transition-opacity duration-1000 group-hover:dark:opacity-100 hidden dark:block"
                    style={{
                        background: useTransform(
                            [smoothX, smoothY],
                            ([x, y]: any[]) => `radial-gradient(400px circle at ${x}px ${y}px, rgba(255,255,255,0.04), transparent 70%)`
                        ),
                    }}
                />

                {/* Main Content Body */}
                <div className="relative z-20 flex-1 flex flex-col h-full">
                    {children ? (
                        // Custom Mode: Render children directly
                        children
                    ) : ( // Simple Mode: Render standard layout
                        <div className="flex flex-col h-full p-8 pt-12">
                            {/* Visual Placeholder Area */}
                            <div className="flex-1 w-full overflow-hidden rounded-xl mb-6 border border-zinc-200/40 dark:border-zinc-800/40 bg-zinc-100/30 dark:bg-zinc-900/30 relative flex items-center justify-center min-h-[140px]">
                                {visual || (
                                    <div className="flex flex-col items-center gap-2 opacity-20">
                                        <Box size={32} />
                                    </div>
                                )}
                                <div className="absolute inset-0 pointer-events-none opacity-0 group-hover:opacity-100 transition-opacity duration-1000 bg-gradient-to-tr from-transparent via-white/[0.03] to-transparent -translate-x-full group-hover:translate-x-full transition-transform ease-in-out" />
                            </div>

                            {/* Labeling & Iconography */}
                            <div className="flex items-center gap-5 text-left mt-auto">
                                <div className="p-3.5 rounded-2xl bg-white dark:bg-zinc-900 border border-zinc-200 dark:border-zinc-800 shrink-0 shadow-sm text-zinc-500 group-hover:bg-zinc-900 group-hover:text-white dark:group-hover:bg-white dark:group-hover:text-zinc-950 transition-all duration-500">
                                    {icon || <ArrowRight size={14} />}
                                </div>
                                <div className="space-y-1 overflow-hidden">
                                    <h3 className="text-[13px] font-black text-zinc-900 dark:text-zinc-100 uppercase tracking-tight truncate">
                                        {title}
                                    </h3>
                                    <div className="text-[11px] leading-relaxed text-zinc-400 dark:text-zinc-500 line-clamp-1 font-medium opacity-80">
                                        {description}
                                    </div>
