"use client";

import React, { useRef, useState } from "react";
import {
    AnimatePresence,
    motion,
    useMotionValue,
    useSpring,
    useTransform,
} from "framer-motion";
import { LayoutGrid } from "lucide-react";
import { cn } from "@/lib/utils";
import Link from "next/link";

export interface FloatingDockItem {
    title: string;
    icon: React.ReactElement; // Using ReactElement to allow cloning for strokeWidth
    href: string;
}

export interface FloatingDockProps {
    items: FloatingDockItem[];
    desktopClassName?: string;
    mobileClassName?: string;
}

export const FloatingDock = ({
    items,
    desktopClassName,
    mobileClassName,
}: FloatingDockProps) => {
    return (
        <>
            <FloatingDockDesktop items={items} className={desktopClassName} />
            <FloatingDockMobile items={items} className={mobileClassName} />
        </>
    );
};

const FloatingDockMobile = ({
    items,
    className,
}: {
    items: FloatingDockItem[];
    className?: string;
}) => {
    const [open, setOpen] = useState(false);
    return (
        <div className={cn("relative block md:hidden w-fit mx-auto", className)}>
            <AnimatePresence>
                {open && (
                    <motion.div
                        layoutId="nav"
                        className="absolute bottom-full mb-4 inset-x-0 flex flex-col gap-3 items-center"
                    >
                        {items?.map((item, idx) => (
                            <motion.div
                                key={item.title}
                                initial={{ opacity: 0, y: 10, scale: 0.8 }}
                                animate={{
                                    opacity: 1,
                                    y: 0,
                                    scale: 1
                                }}
                                exit={{
                                    opacity: 0,
                                    y: 10,
                                    scale: 0.8,
                                    transition: {
                                        delay: idx * 0.05,
                                    },
                                }}
                                transition={{ type: "spring", stiffness: 300, damping: 20, delay: (items.length - 1 - idx) * 0.05 }}
                            >
                                <Link
                                    href={item.href}
                                    className="h-12 w-12 rounded-2xl bg-white dark:bg-zinc-900 flex items-center justify-center border border-zinc-200 dark:border-zinc-800 shadow-xl"
                                >
                                    <div className="h-5 w-5">{item.icon}</div>
                                </Link>
                            </motion.div>
                        ))}
                    </motion.div>
                )}
            </AnimatePresence>
            <button
                onClick={() => setOpen(!open)}
                className="h-12 w-12 rounded-2xl bg-zinc-900 dark:bg-white flex items-center justify-center shadow-2xl transition-transform active:scale-90"
            >
                <LayoutGrid className="h-6 w-6 text-white dark:text-zinc-900" />
            </button>
        </div>
    );
};

const FloatingDockDesktop = ({
    items,
    className,
}: {
    items: FloatingDockItem[];
    className?: string;
}) => {
    let mouseX = useMotionValue(Infinity);
    return (
        <motion.div
            onMouseMove={(e) => mouseX.set(e.pageX)}
            onMouseLeave={() => mouseX.set(Infinity)}
            className={cn(
                "mx-auto hidden md:flex h-20 gap-4 items-end rounded-[2.5rem] bg-white/40 dark:bg-zinc-950/40 backdrop-blur-3xl px-6 pb-4 border border-zinc-200/50 dark:border-zinc-800/50 shadow-[0_30px_60px_-15px_rgba(0,0,0,0.1)] dark:shadow-[0_30px_60px_-15px_rgba(0,0,0,0.5)] w-fit",
                className
            )}
        >
            {items?.map((item) => (
                <IconContainer mouseX={mouseX} key={item.title} {...item} />
            ))}
        </motion.div>
    );
};

function IconContainer({
    mouseX,
    title,
    icon,
    href,
}: {
    mouseX: any;
    title: string;
    icon: React.ReactElement;
    href: string;
}) {
    let ref = useRef<HTMLDivElement>(null);

    let distance = useTransform(mouseX, (val: number) => {
        let bounds = ref.current?.getBoundingClientRect() ?? { x: 0, width: 0 };
        return val - bounds.x - bounds.width / 2;
    });

    // Proximity Scaling - Iconic Zen "Liquid" feel
    let widthSync = useTransform(distance, [-150, 0, 150], [44, 90, 44]);
    let heightSync = useTransform(distance, [-150, 0, 150], [44, 90, 44]);

    // Floating Effect - Lift icons as they scale
    let ySync = useTransform(distance, [-150, 0, 150], [0, -12, 0]);

    // Dynamic Stroke - Icons get bolder when focused
    let strokeSync = useTransform(distance, [-150, 0, 150], [1.5, 2.5, 1.5]);

    let width = useSpring(widthSync, { mass: 0.1, stiffness: 200, damping: 15 });
    let height = useSpring(heightSync, { mass: 0.1, stiffness: 200, damping: 15 });
    let y = useSpring(ySync, { mass: 0.1, stiffness: 200, damping: 15 });
    let strokeWidth = useSpring(strokeSync, { mass: 0.1, stiffness: 200, damping: 15 });

    const [hovered, setHovered] = useState(false);

    return (
        <Link href={href}>
            <motion.div
                ref={ref}
                style={{ width, height, y }}
                onMouseEnter={() => setHovered(true)}
                onMouseLeave={() => setHovered(false)}
                className="aspect-square rounded-[1.5rem] bg-zinc-50 dark:bg-zinc-900 flex items-center justify-center relative shadow-sm border border-zinc-200 dark:border-zinc-800 hover:border-zinc-400 dark:hover:border-zinc-600 transition-colors group/dock-item"
            >
                {/* Internal Glow Effect */}
                <motion.div
                    className="absolute inset-0 rounded-[1.5rem] bg-gradient-to-t from-zinc-200/50 to-transparent dark:from-white/5 opacity-0 group-hover/dock-item:opacity-100 transition-opacity"
                />

                <AnimatePresence>
                    {hovered && (
                        <motion.div
                            initial={{ opacity: 0, y: 10, x: "-50%", scale: 0.9 }}
                            animate={{ opacity: 1, y: -45, x: "-50%", scale: 1 }}
                            exit={{ opacity: 0, y: 10, x: "-50%", scale: 0.9 }}
                            transition={{ type: "spring", stiffness: 400, damping: 25 }}
                            className="px-3 py-1 whitespace-pre rounded-xl bg-zinc-950 dark:bg-white text-white dark:text-zinc-950 absolute left-1/2 -top-8 w-fit text-[10px] font-black uppercase tracking-widest shadow-2xl z-50 pointer-events-none"
                        >
                            {title}
                            <div className="absolute -bottom-1 left-1/2 -translate-x-1/2 w-2 h-2 rotate-45 bg-zinc-950 dark:bg-white" />
                        </motion.div>
                    )}
                </AnimatePresence>

                <motion.div
                    className="flex items-center justify-center w-full h-full p-2"
                >
                    {React.cloneElement(icon, {
                        // @ts-ignore - Dynamically injecting strokeWidth for Lucide icons
                        strokeWidth: strokeWidth.get(),
                        className: cn("w-1/2 h-1/2 transition-colors", hovered ? "text-zinc-900 dark:text-white" : "text-zinc-500")
                    })}
                </motion.div>

                {/* Indicator Dot */}
                {hovered && (
                    <motion.div
                        layoutId="indicator"
                        className="absolute -bottom-2 left-1/2 -translate-x-1/2 w-1 h-1 rounded-full bg-zinc-900 dark:bg-white"
                    />
                )}
            </motion.div>
        </Link>
    );
}

"use client";

import React, { useRef, useMemo } from 'react';
import { gsap, Observer } from 'gsap/all';
import { useGSAP } from '@gsap/react';
import { cn } from "@/lib/utils";

/**
 * ImageGallery Component
 * "Production-Level" Infinite Scroll Carousel
 * 
 * Features:
 * - Seamless infinite loop (using 2x dupe + wrapping)
 * - Premium, contained styling (no overflow mess)
 */

export const DEFAULT_IMAGES = [
    {
        url: "https://images.unsplash.com/photo-1506744038136-46273834b3fb?q=80&w=1200&auto=format&fit=crop",
        title: "Ethereal Valley",
        tag: "Nature"
    },
    {
        url: "https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?q=80&w=1200&auto=format&fit=crop",
        title: "Mist Peaks",
        tag: "Atmosphere"
    },
    {
        url: "https://images.unsplash.com/photo-1441974231531-c6227db76b6e?q=80&w=1200&auto=format&fit=crop",
        title: "Infinite Forest",
        tag: "Serenity"
    },
    {
        url: "https://images.unsplash.com/photo-1501785888041-af3ef285b470?q=80&w=1200&auto=format&fit=crop",
        title: "Glass Lake",
        tag: "Reflection"
    },
    {
        url: "https://images.unsplash.com/photo-1447752875215-b2761acb3c5d?q=80&w=1200&auto=format&fit=crop",
        title: "Zen Bridge",
        tag: "Path"
    },
    {
        url: "https://images.unsplash.com/photo-1472214103451-9374bd1c798e?q=80&w=1200&auto=format&fit=crop",
        title: "Crimson Horizon",
        tag: "Twilight"
    },
];

gsap.registerPlugin(Observer);

export interface ImageGalleryItem {
    url: string;
    title: string;
    tag: string;
}

export interface ImageGalleryProps {
    className?: string;
    items?: ImageGalleryItem[];
}

export const ImageGallery: React.FC<ImageGalleryProps> = ({
    className,
    items = DEFAULT_IMAGES
}) => {
    const containerRef = useRef<HTMLDivElement>(null);
    const trackRef = useRef<HTMLDivElement>(null);

    // Duplicate items for seamless loop (triple buffer is safest for wide screens)
    // If items is empty/undefined, handle gracefully
    const displayItems = useMemo(() => {
        if (!items || items.length === 0) return [];
        return [...items, ...items, ...items];
    }, [items]);

    useGSAP(() => {
        if (!containerRef.current || !trackRef.current) return;
        if (displayItems.length === 0) return;

        const track = trackRef.current;
        const allItems = gsap.utils.toArray<HTMLElement>('.gallery-item');

        if (allItems.length === 0) return;

        // Layout Config (Dynamic)
        // We need to wait for layout or use hardcoded assumptions if rendered yet
        // Since we are in useGSAP, elements should be mounted.
        const itemWidth = allItems[0].offsetWidth;
        const gap = parseFloat(window.getComputedStyle(track).gap) || 32;
        const totalItemWidth = itemWidth + gap;
        const groupWidth = items.length * totalItemWidth;

        // Initialize position
        // Center the initial view in the middle set of images
        let xPos = -groupWidth;
        gsap.set(track, { x: xPos });

        let isDragging = false;
        let velocity = 0;

        const updateLoop = () => {
            // Friction
            velocity *= 0.92;
            xPos += velocity;

            // Seamless Wrapping Logic
            // If we've scrolled past the first set, wrap back to end
            if (xPos > 0) {
                xPos = -groupWidth;
            }
            // If we've scrolled past the second set, wrap back to start
            else if (xPos < -groupWidth * 2) {
                xPos = -groupWidth;
            }

            gsap.set(track, { x: xPos });

            // Apply Parallax to inner images based on velocity
            // More velocity = more skew/parallax
            const skewAmount = gsap.utils.clamp(-5, 5, velocity * 0.5);
            gsap.set(allItems, { skewX: skewAmount });
        };

        const loop = gsap.to({}, { duration: 1 / 60, repeat: -1, onRepeat: updateLoop });

        // Auto-scroll drift
        let driftStrength = -0.5;

        // GSAP Observer for Touch/Wheel/Drag
        const observer = Observer.create({
            target: containerRef.current,
            type: "wheel,touch,pointer",
            onPress: () => {
                isDragging = true;
                driftStrength = 0; // Pause auto-drift while interacting
                document.body.style.cursor = 'grabbing';
            },
            onRelease: () => {
                isDragging = false;
                driftStrength = -0.5; // Resume drift
                document.body.style.cursor = 'default';
            },
            onChange: (self) => {
                const delta = self.deltaX || self.deltaY; // vertical scroll wheel -> horizontal drift
                velocity += -delta * 0.05;
            }
        });

        // Add constant drift to velocity
        gsap.ticker.add(() => {
            if (!isDragging) {
                velocity += driftStrength * 0.05;
            }
        });

        // Local Interactions (Hover, Tilt)
        allItems.forEach((el) => {
            const item = el as HTMLElement;
            const img = item.querySelector('img');
            const overlay = item.querySelector('.overlay');

            item.addEventListener('mouseenter', () => {
                if (isDragging) return;
                gsap.to(item, { scale: 1.02, duration: 0.4, ease: "power2.out" });
                gsap.to(img, { scale: 1.15, duration: 0.4, ease: "power2.out" });
                gsap.to(overlay, { opacity: 1, duration: 0.4 });
            });

            item.addEventListener('mouseleave', () => {
                gsap.to(item, { scale: 1, duration: 0.4, ease: "power2.out" });
                gsap.to(img, { scale: 1.05, duration: 0.4, ease: "power2.out" }); // Keep slightly scaled for parallax
                gsap.to(overlay, { opacity: 0, duration: 0.4 });
            });
        });

        return () => {
            loop.kill();
            observer.kill();
            gsap.ticker.remove(containerRef.current as any); // cleanup ticker listener
        };

    }, { scope: containerRef, dependencies: [displayItems] });

    return (
        <div
            ref={containerRef}
            className={cn(
                "relative w-full h-[400px] md:h-[600px] overflow-hidden bg-zinc-50 dark:bg-transparent flex flex-col justify-center select-none cursor-grab active:cursor-grabbing",
                className
            )}
        >
            {/* Cinematic Fade Edges */}
            <div className="absolute inset-y-0 left-0 w-32 bg-gradient-to-r from-zinc-50 to-transparent dark:from-transparent z-20 pointer-events-none" />
            <div className="absolute inset-y-0 right-0 w-32 bg-gradient-to-l from-zinc-50 to-transparent dark:from-transparent z-20 pointer-events-none" />

            {/* Title / Header (Optional) */}
            <div className="absolute top-4 left-0 w-full text-center z-10 pointer-events-none opacity-40">
                <p className="text-[10px] uppercase tracking-[0.4em] font-bold">Infinite Series</p>
            </div>

            {/* TRACK */}
            <div
                ref={trackRef}
                className="flex gap-4 md:gap-8 px-4 md:px-8 items-center"
                style={{ width: 'max-content' }}
            >
                {displayItems.map((item, i) => (
                    <div
                        key={i}
                        className="gallery-item relative w-[220px] md:w-[320px] aspect-[3/4] rounded-2xl overflow-hidden bg-zinc-200 dark:bg-zinc-800 shadow-xl border border-white/20 dark:border-white/5 WillChangeTransform"
                    >
                        {/* Image Container */}
                        <div className="absolute inset-0 overflow-hidden">
                            <img
                                src={item.url}
                                alt={item.title}
                                className="w-full h-full object-cover scale-105 transition-transform duration-700 will-change-transform"
                            />
                        </div>

                        {/* Minimalist Overlay */}
                        <div className="overlay absolute inset-0 bg-black/40 opacity-0 transition-opacity duration-300 flex flex-col justify-end p-6">
                            <p className="text-[10px] text-white/70 uppercase tracking-widest">{item.tag}</p>
                            <h3 className="text-xl text-white font-medium mt-1">{item.title}</h3>
                        </div>
                    </div>
                ))}
            </div>

            {/* Progress / Hint */}
            <div className="absolute bottom-4 left-0 w-full text-center z-10 pointer-events-none opacity-40">
                <p className="text-[10px] uppercase tracking-[0.2em]">Drag to Explore</p>
            </div>
        </div>
    );
};

"use client";

import React, { useRef, useEffect, useState } from "react";
import { useGSAP } from "@gsap/react";
import gsap from "gsap";
import { cn } from "@/lib/utils";

export const DEFAULT_IMAGES = [
    "https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?q=80&w=2000&auto=format&fit=crop",
    "https://images.unsplash.com/photo-1501854140801-50d01698950b?q=80&w=2000&auto=format&fit=crop",
    "https://images.unsplash.com/photo-1441974231531-c6227db76b6e?q=80&w=2000&auto=format&fit=crop",
    "https://images.unsplash.com/photo-1506744038136-46273834b3fb?q=80&w=2000&auto=format&fit=crop",
    "https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?q=80&w=2000&auto=format&fit=crop",
    "https://images.unsplash.com/photo-1502082553048-f009c37129b9?q=80&w=2000&auto=format&fit=crop",
    "https://images.unsplash.com/photo-1433086966358-54859d0ed716?q=80&w=2000&auto=format&fit=crop",
];

interface ImageTrailProps {
    images?: string[];
    className?: string;
    containerClassName?: string;
}

export const ImageTrail = ({
    images = DEFAULT_IMAGES,
    className,
    containerClassName,
}: ImageTrailProps) => {
    const containerRef = useRef<HTMLDivElement>(null);
    const imagesRef = useRef<HTMLDivElement[]>([]);
    const lastX = useRef(0);
    const lastY = useRef(0);
    const zIndex = useRef(1);
    const activeIndex = useRef(0);

    // Initial setup: hide all images
    useGSAP(() => {
        gsap.set(imagesRef.current, {
            opacity: 0,
            scale: 0.5,
            xPercent: -50,
            yPercent: -50,
            visibility: "hidden"
        });
    }, { scope: containerRef });

    const spawnImage = (x: number, y: number) => {
        const dist = Math.hypot(x - lastX.current, y - lastY.current);

        if (dist > 60) {
            const img = imagesRef.current[activeIndex.current];
            if (img) {
                zIndex.current += 1;

                // Reset and clear any existing animation on this specific element
                gsap.killTweensOf(img);

                // Animate from cursor position
                gsap.fromTo(img,
                    {
                        x: x,
                        y: y,
                        scale: 0.5,
                        opacity: 0,
                        visibility: "visible",
                        rotate: Math.random() * 30 - 15,
                        zIndex: zIndex.current
                    },
                    {
                        scale: 1,
                        opacity: 1,
                        duration: 0.4,
                        ease: "back.out(2)",
                        onComplete: () => {
                            // Fade out after a short delay
                            gsap.to(img, {
                                opacity: 0,
                                scale: 0.8,
                                delay: 1,
                                duration: 0.8,
                                ease: "power2.inOut",
                                onComplete: () => {
                                    gsap.set(img, { visibility: "hidden" });
                                }
                            });
                        }
                    }
                );

                // Update trackers
                activeIndex.current = (activeIndex.current + 1) % images.length;
                lastX.current = x;
                lastY.current = y;
            }
        }
    };

    const handleMouseMove = (e: React.MouseEvent) => {
        if (!containerRef.current) return;
        const rect = containerRef.current.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;
        spawnImage(x, y);
    };

    const handleTouchMove = (e: React.TouchEvent) => {
        if (!containerRef.current) return;
        const rect = containerRef.current.getBoundingClientRect();
        const touch = e.touches[0];
        const x = touch.clientX - rect.left;
        const y = touch.clientY - rect.top;
        spawnImage(x, y);
    };

    return (
        <div
            ref={containerRef}
            onMouseMove={handleMouseMove}
            onTouchMove={handleTouchMove}
            className={cn(
                "relative w-full h-[400px] md:h-[600px] overflow-hidden bg-zinc-50 dark:bg-zinc-950 rounded-[3rem] border border-zinc-200 dark:border-zinc-800 cursor-crosshair group touch-none",
                containerClassName
            )}
        >
            {/* Background Decor */}
            <div className="absolute inset-0 opacity-[0.05] pointer-events-none"
                style={{ backgroundImage: 'radial-gradient(circle, currentColor 1px, transparent 1px)', backgroundSize: '30px 30px' }} />

            <div className="absolute inset-0 flex flex-col items-center justify-center text-center z-10 pointer-events-none select-none">
                <h2 className="text-3xl sm:text-4xl md:text-6xl font-black uppercase tracking-tighter text-zinc-900 dark:text-white">
                    Visual <span className="text-blue-500">Echo</span>
                </h2>
                <p className="mt-4 text-[10px] sm:text-xs font-black uppercase tracking-[0.4em] text-zinc-500 opacity-60">
                    Trace the movement
                </p>
            </div>

            {/* Trail Elements */}
            {images.map((src, i) => (
                <div
                    key={i}
                    ref={(el) => { if (el) imagesRef.current[i] = el; }}
                    className={cn(
                        "absolute pointer-events-auto rounded-3xl overflow-hidden shadow-2xl border-2 border-white dark:border-zinc-800 transition-transform duration-300 hover:scale-110",
                        className
                    )}
                    style={{ width: '200px', height: '260px' }}
                >
                    <img
                        src={src}
                        alt="echo"
                        className="w-full h-full object-cover"
                        loading="lazy"
                    />
                </div>
            ))}
        </div>
    );
};

"use client";

import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { motion, AnimatePresence, useSpring, useMotionValue, useTransform } from 'framer-motion';
import { cn } from '@/lib/utils';
import { Cpu, Globe, Zap, Shield, Database, Cloud } from "lucide-react";

export type LogoItem = {
    src?: string;
    node?: React.ReactNode;
    alt?: string;
    name?: string;
};

export const DEFAULT_LOGOS: LogoItem[] = [
    { node: <Cpu size={20} className="text-blue-500" />, name: "Compute" },
    { node: <Globe size={20} className="text-emerald-500" />, name: "Edge" },
    { node: <Zap size={20} className="text-yellow-500" />, name: "Fast" },
    { node: <Shield size={20} className="text-purple-500" />, name: "Secure" },
    { node: <Database size={20} className="text-orange-500" />, name: "Storage" },
    { node: <Cloud size={20} className="text-cyan-500" />, name: "Cloud" },
];

interface LogoLoopProps {
    items?: LogoItem[];
    speed?: number;
    direction?: 'left' | 'right';
    gap?: number;
    logoHeight?: number;
    pauseOnHover?: boolean;
    className?: string;
}

const ANIMATION_CONFIG = {
    SMOOTH_TAU: 0.2, // Faster response than reference
    MIN_COPIES: 2,
} as const;

/* -------------------------------------------------------------------------- */
/*                               LOGO BOX COMPONENT                           */
/* -------------------------------------------------------------------------- */

const LogoBox = ({ item, height }: { item: LogoItem; height: number }) => {
    const mouseX = useMotionValue(0);
    const mouseY = useMotionValue(0);

    const rotateX = useSpring(useTransform(mouseY, [-0.5, 0.5], [15, -15]), { stiffness: 300, damping: 30 });
    const rotateY = useSpring(useTransform(mouseX, [-0.5, 0.5], [-15, 15]), { stiffness: 300, damping: 30 });

    const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
        const rect = e.currentTarget.getBoundingClientRect();
        const x = (e.clientX - rect.left) / rect.width - 0.5;
        const y = (e.clientY - rect.top) / rect.height - 0.5;
        mouseX.set(x);
        mouseY.set(y);
    };

    const handleMouseLeave = () => {
        mouseX.set(0);
        mouseY.set(0);
    };

    return (
        <motion.div
            onMouseMove={handleMouseMove}
            onMouseLeave={handleMouseLeave}
            style={{ rotateX, rotateY, height, perspective: 1000 }}
            className="relative flex items-center justify-center px-8 py-4 bg-zinc-50 dark:bg-zinc-900/50 border border-zinc-200 dark:border-zinc-800 rounded-2xl group/logo transition-colors hover:bg-white dark:hover:bg-zinc-800 hover:border-zinc-300 dark:hover:border-zinc-700 shadow-sm hover:shadow-xl group"
        >
            {/* Glint Effect */}
            <motion.div
                className="absolute inset-0 opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none overflow-hidden rounded-2xl"
            >
                <div className="absolute inset-0 bg-gradient-to-tr from-transparent via-white/20 to-transparent translate-x-[-100%] group-hover:translate-x-[200%] transition-transform duration-1000 ease-in-out" />
            </motion.div>

            {item.node ? (
                <div className="flex items-center gap-3">
                    {item.node}
                    {item.name && <span className="text-xs font-black uppercase tracking-widest text-zinc-400 group-hover:text-zinc-900 dark:group-hover:text-white transition-colors">{item.name}</span>}
                </div>
            ) : (
                <img
                    src={item.src}
                    alt={item.alt || "logo"}
                    className="h-full w-auto grayscale group-hover:grayscale-0 transition-all duration-500 opacity-50 group-hover:opacity-100 scale-90 group-hover:scale-100"
                />
            )}
        </motion.div>
    );
};

